/// Returns true iff `v` starts with prefix `p` under the problem definition.
///
/// - If `p` is empty, returns true.
/// - Otherwise, returns true iff `v.len() >= p.len()` and all characters match
///   for positions `0..p.len()`.
pub fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    if p.is_empty() {
        return true;
    }
    if v.len() < p.len() {
        return false;
    }
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

/// Filters `xs`, keeping exactly those sequences that start with prefix `p`.
/// The relative order of kept sequences is preserved.
pub fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut filtered: Vec<Vec<char>> = Vec::with_capacity(xs.len());
    for s in xs.into_iter() {
        if has_prefix(&s, &p) {
            filtered.push(s);
        }
    }
    filtered
}

